const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/u;

const SNOWFLAKE = /^[0-9]{1,32}$/u;

type CoachingPlanItemInput=Omit<TraderLinkCommunityCoachingPlanItem,"planItemId"|"ordinal">;

function text(value: string, maximum: number, field: string, required = true): string {
  const normalized = value.normalize("NFKC").trim();
  const multiline=["body","description","paymentInstructions","biography","deliverySummary","message","studentContext","coachFeedback","wentWell","needsWork","nextFocus","coachPrivateNotes","previousFocusAssessment","recordBody"].includes(field);
  const controls=multiline?/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u:/[\u0000-\u001f\u007f]/u;
  if ((required && !normalized) || normalized.length > maximum || controls.test(normalized)) {
    platformFailure("TRADERLINK_PLATFORM_STORAGE_VALIDATION_FAILED", { field });
  }
  return normalized;
}

function slug(value: string, field: string): string {
  const normalized = text(value, 100, field).toLowerCase().replace(/[^a-z0-9]+/gu, "-").replace(/^-|-$/gu, "");
  if (!SLUG.test(normalized)) platformFailure("TRADERLINK_PLATFORM_STORAGE_VALIDATION_FAILED", { field });
  return normalized;
}

type BaseViewer = Readonly<{ userId: string; displayName: string; discordRoleIds: readonly string[] }>;

function parseJsonStrings(value: string): readonly string[] {
  try {
    const parsed: unknown = JSON.parse(value);
    return Array.isArray(parsed) && parsed.every((item) => typeof item === "string") ? Object.freeze(parsed) : Object.freeze([]);
  } catch { return Object.freeze([]); }
}

