    if(!relationship||relationship.coach_user_id!==input.actor.userId||relationship.status!=="active")platformFailure("TRADERLINK_WORKSPACE_ACCESS_DENIED",{operation:"create_coaching_task"});this.requireCurrentCoachingRole(input.communityId,input.relationshipId);
    const id=createCanonicalUuidV4();this.database.prepare(`INSERT INTO traderlink_community_coaching_tasks(task_id,relationship_id,community_id,created_by_user_id,title,due_at_utc,priority,status,created_at_utc,completed_at_utc,updated_at_utc) VALUES(?,?,?,?,?,?,?,'open',?,NULL,?)`).run(id,input.relationshipId,input.communityId,input.actor.userId,text(input.title,160,"taskTitle"),input.dueAtUtc??null,input.priority,input.atUtc,input.atUtc);return id;
